136	\subsection*{Governing-law structures}
137	
138	\begin{definition}[Lawful two-body dissociation]
139	\label{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsTwoBodyDissociation}
140	\lean{IPhO2026.Problem1.C1.IsTwoBodyDissociation}
141	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:PhotonLine, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:ReactionPlane, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsScatteringAngle}
142	The governing-law structure of the absorption and two-body breakup
143	$\gamma + O_3 \to O_2 + O$ at photon angular frequency $\omega$: vector
144	momentum conservation fixes the oxygen-atom momentum
145	$q = (\hbar\omega/c)\,\hat{k} - p$; its eliminated cosine-law shadow is
146	$\|q\|^2 = (\hbar\omega/c)^2 + \|p\|^2 - 2(\hbar\omega/c)\,\|p\|\cos\theta$;
147	$\theta$ is the Figure-1c scattering angle; and non-relativistic energy
148	balance reads $\hbar\omega = \Delta U + \|p\|^2/(2\cdot 2m) + \|q\|^2/(2m)$
149	with fragment masses $2m$ and $m$.  No field mentions the threshold value.
150	\end{definition}
151	\begin{proof}
152	Definition; no claim.
153	\end{proof}
154	
155	\begin{lemma}[Cosine-law elimination from vector momentum balance]
156	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:momentum_q_sq_of_vector_balance}
157	\lean{IPhO2026.Problem1.C1.momentum_q_sq_of_vector_balance}
158	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:PhotonLine, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsScatteringAngle}
159	If $q = (\hbar\omega/c)\,\hat{k} - p$ and $\theta$ is the scattering angle
160	between $\hat{k}$ and $p$, then
161	$\|q\|^2 = (\hbar\omega/c)^2 + \|p\|^2 - 2(\hbar\omega/c)\,\|p\|\cos\theta$:
162	the scalar magnitude field of the dissociation structure is a genuine
163	consequence of the vector law, not an independent modelling assumption.
164	\end{lemma}
165	\begin{proof}
166	Expand $\|q\|^2 = \langle q, q \rangle$ with $q$ given by the vector
167	balance, use $\|\hat{k}\| = 1$ for the quadratic term, and insert the
168	readout $\langle \hat{k}, p \rangle = \|p\|\cos\theta$ for the cross term.
169	\end{proof}
170	
171	\begin{definition}[Reachable frequency]
172	\label{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:ReachableFrequency}
173	\lean{IPhO2026.Problem1.C1.ReachableFrequency}
174	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsTwoBodyDissociation}
175	A photon angular frequency $\omega$ is reachable at outgoing $O_2$ angle
176	$\theta$ (atom mass $m$, dissociation gap $\Delta U$) iff some lawful
177	dissociation configuration realizes that frequency: an existential over
178	photon directions and fragment momenta, not a formula.
179	\end{definition}
180	\begin{proof}
181	Definition; no claim.
182	\end{proof}
183	
184	\begin{definition}[Dissociation threshold]
185	\label{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsDissociationThreshold}
186	\lean{IPhO2026.Problem1.C1.IsDissociationThreshold}
187	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:ReachableFrequency}
188	$\omega_0$ is a dissociation threshold at angle $\theta$ iff it is
189	reachable and no strictly smaller positive frequency is reachable: a pure
190	minimality property that leaves the numerical value of the threshold open.
191	\end{definition}
192	\begin{proof}
193	Definition; no claim.
194	\end{proof}
195	
196	\subsection*{Threshold candidate and derivation bridges}
197	
198	\begin{definition}[Candidate threshold expression]
199	\label{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin}
200	\lean{IPhO2026.Problem1.C1.hbarOmegaMin}
201	The candidate closed-form forward-branch threshold
202	$\Omega(m, c, \Delta U, \theta)$ of the official solution, named as a bare
203	real-valued expression of the problem data (built from the angular factor
204	$2\sin^2\theta + 1$ and the square root of its discriminant).  By itself it
205	asserts nothing about dissociation; the claim that it \emph{is} the minimum
206	reachable frequency is the content of the target theorems below.
207	\end{definition}
208	\begin{proof}
209	Definition; no claim.
210	\end{proof}
211	
212	\begin{lemma}[Angular-factor identity]
213	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:two_sin_sq_add_one_eq}
214	\lean{IPhO2026.Problem1.C1.two_sin_sq_add_one_eq}
215	For every angle $\theta$, $2\sin^2\theta + 1 = 2 - \cos 2\theta$: the
216	angular factor of the threshold formula equals the coefficient appearing in
217	the official quadratic characterization.
218	\end{lemma}
219	\begin{proof}
220	The double-angle identity $\cos 2\theta = 1 - 2\sin^2\theta$ rearranged.
221	\end{proof}
222	
223	\begin{lemma}[Quadratic characterization of the candidate threshold]
224	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:quadratic_characterization_of_threshold}
225	\lean{IPhO2026.Problem1.C1.quadratic_characterization_of_threshold}
226	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsForwardBranch, lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:two_sin_sq_add_one_eq}
227	For positive $m, c, \Delta U$, a forward angle $0 < \theta \le \pi/2$ with
228	nondegenerate angular factor $2 - \cos 2\theta \neq 0$ and a real square
229	root in the candidate formula, the scaled candidate
230	$E_0 = \hbar\,\Omega(m,c,\Delta U,\theta)$ is positive, solves
231	$(2 - \cos 2\theta)\,E^2 - 6 m c^2 E + 6\,\Delta U\,m c^2 = 0$,
232	and is smaller than every other positive root: it is the smallest positive
233	root of the official-solution quadratic.
234	\end{lemma}
235	\begin{proof}
236	Rewrite $2\sin^2\theta + 1$ as $2 - \cos 2\theta$ via the angular-factor
237	identity, so the candidate becomes the root of the displayed quadratic in
238	$E = \hbar\omega$ selected by the minus sign of the quadratic formula;
239	positivity follows from the positive regime and the real square root, and
240	minimality among positive roots because the two roots are ordered by that
241	sign choice.
242	\end{proof}
243	
244	\subsection*{Value and target theorems}
245	
246	\begin{theorem}[Minimum angular frequency, forward branch]
247	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:minimum_angular_frequency_T1_C1}
248	\lean{IPhO2026.Problem1.C1.minimum_angular_frequency_T1_C1}
249	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:ConstantRegime, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsAngularRange, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsForwardBranch, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsDissociationThreshold, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin, lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:quadratic_characterization_of_threshold, lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:momentum_q_sq_of_vector_balance}
250	In the positive-constant regime, for a nondegenerate forward angle
251	$0 < \theta \le \pi/2$ with a real square root, the candidate expression
252	\[
253	\Omega(m,c,\Delta U,\theta)
254	= \frac{3 m c^2 \left(1 - \sqrt{1 - \frac{\Delta U}{3 m c^2}\,(2\sin^2\theta + 1)}\right)}{\hbar\,(2\sin^2\theta + 1)}
255	\]
256	is the dissociation threshold at $\theta$: some lawful two-body
257	configuration realizes it, and no smaller positive frequency is reachable.
258	The recorded closed form appears strictly on the conclusion side; the
259	hypotheses carry only the physical regime, the figure angle range, and the
260	algebraic nondegeneracy.
261	\end{theorem}
262	\begin{proof}
263	Eliminate $\|p\|$ between the energy-balance and cosine-law fields of a
264	lawful configuration at frequency $\omega$: reachability at forward angle
265	$\theta$ reduces to the official-solution quadratic in $\hbar\omega$
266	having a real solution, which holds exactly at and above its smallest
267	positive root.  By the quadratic characterization that root is
268	$\hbar\,\Omega$, so $\Omega$ is reachable and minimal.
269	\end{proof}
270	
271	\begin{theorem}[Minimum angular frequency, backward branch]
272	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:minimum_angular_frequency_backward_branch_T1_C1}
273	\lean{IPhO2026.Problem1.C1.minimum_angular_frequency_backward_branch_T1_C1}
274	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:ConstantRegime, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsAngularRange, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:IsDissociationThreshold, def:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin, thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:minimum_angular_frequency_T1_C1, thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin_pi_sub}
275	In the positive-constant regime, for a backward angle
276	$\pi/2 \le \theta \le \pi$ with a real square root (at $\theta = \pi/2$),
277	the dissociation threshold freezes at its $\theta = \pi/2$ value: the
278	threshold at $\theta$ is the forward-branch candidate evaluated at
279	$\pi/2$, $\Omega(m, c, \Delta U, \pi/2)$.  The recorded answer again
280	occurs only in the conclusion.
281	\end{theorem}
282	\begin{proof}
283	The tangent-line critical configuration of Figure~1c exists only in the
284	forward branch, so for $\theta \ge \pi/2$ the binding constraint is the
285	$\pi/2$ one; formally this rests on the forward-branch threshold theorem
286	at $\pi/2$ together with the reflection symmetry of the candidate formula.
287	\end{proof}
288	
289	\begin{theorem}[Reflection symmetry of the candidate threshold]
290	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin_pi_sub}
291	\lean{IPhO2026.Problem1.C1.hbarOmegaMin_pi_sub}
292	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_C_1:hbarOmegaMin}
293	The candidate threshold is invariant under the reflection
294	$\theta \mapsto \pi - \theta$:
295	$\Omega(m, c, \Delta U, \pi - \theta) = \Omega(m, c, \Delta U, \theta)$,
296	the pure-math symmetry justifying the backward-branch freeze.
297	\end{theorem}
298	\begin{proof}
299	The candidate expression depends on $\theta$ only through $\sin^2\theta$,
300	and $\sin(\pi - \theta) = \sin\theta$.
301	\end{proof}
